package org.slavicmyths.finist;
import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.saveddata.SavedData;import net.minecraft.world.phys.*;import net.minecraft.world.level.ClipContext;import org.slavicmyths.skim.HeroCalls;
/** Addressed transient encounters. Saved ACTIVE jobs reset; never acquire chunk tickets. */
public final class KartausEncounter extends SavedData {
 public enum Status{STARTING,ACTIVE,DONE,ABANDONED}
 public static final class Entry{public UUID id=UUID.randomUUID(),owner,hero,boss;public Vec3 center;public long started,outsideAt;public Status status=Status.STARTING;public boolean ownerHit,retreated;}
 public final Map<UUID,Entry> entries=new HashMap<>();
 public static KartausEncounter get(ServerLevel w){return w.getServer().overworld().getDataStorage().computeIfAbsent(new Factory<>(KartausEncounter::new,KartausEncounter::load),"slavicmyths_kartaus_174");}
 public Entry owner(UUID owner){return entries.values().stream().filter(e->owner.equals(e.owner)&&(e.status==Status.ACTIVE||e.status==Status.STARTING)).findFirst().orElse(null);}
 public boolean near(ServerLevel w,Vec3 p){if(w.dimension()!=net.minecraft.world.level.Level.OVERWORLD)return false;return entries.values().stream().anyMatch(e->(e.status==Status.ACTIVE||e.status==Status.STARTING)&&e.center.distanceToSqr(p)<48*48);}
 public boolean active(UUID id){var e=entries.get(id);return e!=null&&(e.status==Status.ACTIVE||e.status==Status.STARTING);}
 public static Vec3 ground(ServerLevel w,Vec3 p,double width,double height){var top=p.add(0,5,0);var end=p.add(0,-4,0);if(!w.hasChunkAt(BlockPos.containing(p)))return null;var hit=w.clip(new ClipContext(top,end,ClipContext.Block.COLLIDER,ClipContext.Fluid.ANY,net.minecraft.world.phys.shapes.CollisionContext.empty()));if(hit.getType()!=HitResult.Type.BLOCK)return null;var at=new Vec3(p.x,hit.getLocation().y+.001,p.z);if(Math.abs(at.y-p.y)>2.5||w.getBlockEntity(hit.getBlockPos())!=null||!HeroCalls.safeSpot(w,at,width,height))return null;return at;}
 public static Vec3 site(ServerPlayer p){var w=p.serverLevel();var d=p.getLookAngle().multiply(1,0,1).normalize();if(d.lengthSqr()<.1)d=new Vec3(0,0,1);var c=ground(w,p.position().add(d.scale(8)),.92,5);if(c==null||!p.hasLineOfSight(newSiteProbe(w,c)))return null;int good=1,innerBlocked=0;for(int r:new int[]{7,14})for(int n=0;n<8;n++){double a=n*Math.PI/4;var q=c.add(Math.cos(a)*r,0,Math.sin(a)*r);var at=ground(w,q,.8,5);if(at!=null&&w.mayInteract(p,BlockPos.containing(at)))good++;else if(r==7)innerBlocked++;}return good>=14&&innerBlocked<=2&&w.mayInteract(p,BlockPos.containing(c))?c:null;}
 private static Entity newSiteProbe(ServerLevel w,Vec3 c){var e=FinistContent.KARTAUS.get().create(w);e.setPos(c);return e;}
 public static void msg(ServerPlayer p,String k){p.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.slavicmyths."+k),true);}
 public static boolean start(ServerPlayer p){var w=p.serverLevel();if(!p.isAlive()||p.isSpectator()||w.dimension()!=net.minecraft.world.level.Level.OVERWORLD){msg(p,"event_no_room");return false;}var d=get(w);if(HeroCalls.battleLocked(p)||d.owner(p.getUUID())!=null||d.near(w,p.position())){msg(p,"event_active");return false;}
 var h=HeroCalls.loaded(p,"finist");if(!(h instanceof FinistEntity f)||h.level()!=w||f.recovering()||f.distanceTo(p)>24){msg(p,"event_hero_required");return false;}if(HeroCalls.count(p)!=1){msg(p,"event_finist_only");return false;}var at=site(p);if(at==null){msg(p,"event_no_room");return false;}
 var e=new Entry();e.owner=p.getUUID();e.hero=f.getUUID();e.center=at;e.started=w.getGameTime();d.entries.put(e.id,e);f.encounter=e.id;f.resetEncounter();d.setDirty();return true;}
 public void tick(ServerLevel w){if(w.getGameTime()%10!=0)return;for(var e:new ArrayList<>(entries.values())){if(e.status!=Status.STARTING&&e.status!=Status.ACTIVE)continue;var p=w.getServer().getPlayerList().getPlayer(e.owner);if(p==null||!p.isAlive()||p.isSpectator()||p.serverLevel()!=w){finish(w,e,false);continue;}double dist=p.position().distanceTo(e.center);if(dist>48){if(e.outsideAt==0)e.outsideAt=w.getGameTime();if(w.getGameTime()-e.outsideAt>=160){finish(w,e,false);continue;}}else e.outsideAt=0;if(dist>36&&w.getGameTime()%100==0)msg(p,"event_return");
 if(e.status==Status.STARTING&&w.getGameTime()-e.started>=32){var h=w.getEntity(e.hero);var b=FinistContent.KARTAUS.get().create(w);if(!(h instanceof FinistEntity f)||b==null||!HeroCalls.safeSpot(w,e.center,.92,2.7)){finish(w,e,false);continue;}b.owner=e.owner;b.encounter=e.id;b.center=e.center;b.moveTo(e.center.x,e.center.y,e.center.z,p.getYRot()+180,0);if(!w.addFreshEntity(b)){finish(w,e,false);continue;}b.begin(FalconAction.INTRO);e.boss=b.getUUID();e.status=Status.ACTIVE;setDirty();}
 if(e.status==Status.ACTIVE&&e.boss!=null&&w.hasChunkAt(BlockPos.containing(e.center))&&!(w.getEntity(e.boss) instanceof KartausEntity)){finish(w,e,false);}
 }}
 public void finish(ServerLevel w,Entry e,boolean victory){if(e.status!=Status.ACTIVE&&e.status!=Status.STARTING)return;e.status=victory?Status.DONE:Status.ABANDONED;var boss=e.boss==null?null:w.getEntity(e.boss);if(boss instanceof KartausEntity b){b.cleanup();if(!victory)b.discard();}if(w.getEntity(e.hero) instanceof FinistEntity f){f.encounter=null;f.clearCurse();if(victory&&!f.recovering()){f.begin(FalconAction.VICTORY);f.cue("entity.finist.victory");}}
 var p=w.getServer().getPlayerList().getPlayer(e.owner);if(p!=null){if(victory){var n=p.getPersistentData();String pre="slavicmyths.story.finist_kartaus.";n.putBoolean(pre+"victory",true);if(!n.contains(pre+"first_victory_at"))n.putLong(pre+"first_victory_at",w.getGameTime());n.putBoolean(pre+"finist_participated",true);n.putInt(pre+"clear_count",n.getInt(pre+"clear_count")+1);n.putBoolean(pre+"pending_reward_1_7_6",true);n.putBoolean(pre+"hero_retreat_during_fight",e.retreated);msg(p,"kartaus_victory");}else msg(p,"event_cancel");}entries.remove(e.id);setDirty();}
 public static KartausEncounter load(CompoundTag n,HolderLookup.Provider p){var d=new KartausEncounter();/* Active records never resume blind casts or summon duplicate helpers. */return d;}
 @Override public CompoundTag save(CompoundTag n,HolderLookup.Provider p){var list=new ListTag();for(var e:entries.values())if(e.status==Status.STARTING||e.status==Status.ACTIVE){var t=new CompoundTag();t.putUUID("Encounter",e.id);t.putUUID("Owner",e.owner);t.putUUID("Finist",e.hero);if(e.boss!=null)t.putUUID("Kartaus",e.boss);t.putString("Dimension","minecraft:overworld");t.putString("Status",e.status.name());t.putLong("Started",e.started);t.putDouble("X",e.center.x);t.putDouble("Y",e.center.y);t.putDouble("Z",e.center.z);list.add(t);}n.put("ResetOnRestart",list);return n;}
}
